/**
 * Copyright (c) Facebook, Inc. and its affiliates.
 *
 * This source code is licensed under the MIT license found in the
 * LICENSE file in the root directory of this source tree.
 */

import {createHash} from 'crypto';
import path from 'path';
import logger from '@docusaurus/logger';
import matter from 'gray-matter';
import GithubSlugger from 'github-slugger';
import _ from 'lodash';
import resolvePathnameUnsafe from 'resolve-pathname';
import {addPrefix, addSuffix, removeSuffix} from './jsUtils';
import {
  WEBPACK_URL_LOADER_LIMIT,
  OUTPUT_STATIC_ASSETS_DIR_NAME,
} from './constants';
import type {
  ParseFrontMatter,
  DefaultParseFrontMatter,
} from '@docusaurus/types';
import type {Slugger, SluggerOptions} from './slugger';
import type {ContentPaths, BrokenMarkdownLink} from './markdownLinks';
import type {Tag, FrontMatterTag} from './tags';
import type {URLPath} from './urlUtils';
import type {RuleSetRule, LoaderContext} from 'webpack';
import type {WebpackCompilerName} from './webpackUtils';

// Some utilities for parsing Markdown content. These things are only used on
// server-side when we infer metadata like `title` and `description` from the
// content. Most parsing is still done in MDX through the mdx-loader.

type AssetFolder = 'images' | 'files' | 'fonts' | 'medias';

type FileLoaderUtils = {
  loaders: {
    file: (options: {folder: AssetFolder}) => RuleSetRule;
    url: (options: {folder: AssetFolder}) => RuleSetRule;
    inlineMarkdownImageFileLoader: string;
    inlineMarkdownAssetImageFileLoader: string;
    inlineMarkdownLinkFileLoader: string;
  };
  rules: {
    images: () => RuleSetRule;
    fonts: () => RuleSetRule;
    media: () => RuleSetRule;
    svg: () => RuleSetRule;
    otherAssets: () => RuleSetRule;
  };
};

type CodeFence = {
  type: '`' | '~';
  definitelyOpen: boolean;
  count: number;
};

type TaggedItemGroup<Item> = {
  tag: Tag;
  items: Item[];
};


type ParseMarkdownContentTitleOptions = {
  /**
   * If `true`, the matching title will be removed from the returned content.
   * We can promise that at least one empty line will be left between the
   * content before and after, but you shouldn't make too much assumption
   * about what's left.
   */
  removeContentTitle?: boolean;
};

export type WriteHeadingIDOptions = SluggerOptions & {
  /** Overwrite existing heading IDs. */
  overwrite?: boolean;
};

/**
 * Coordinates Markdown parsing, MDX preprocessing, link rewriting, tag
 * grouping, URL/path normalization and asset loader generation. Content plugins
 * and the MDX loader go through this processor so document metadata stays
 * consistent across the pipeline.
 */
class MarkdownContentProcessor {
  private headingProcessing = {
    customIdPattern: /\s*\{#(?<id>(?:.(?!\{#|\}))*.)\}$/,
    markdownHeadingRegexp: /(?:^|\n)#{1,6}(?!#).*/g,
    headingIdWritePrefix: '##',
    codeFencePrefix: '```',
    maxHeadingLevel: 6,
    defaultMaintainCase: false,
    defaultOverwrite: false,
  };

  private mdxFenceProcessing = {
    infoString: 'mdx-code-block',
    newline: '\\n',
    spaceClass: '\\x20*',
    headingIdsCompatDefault: true,
  };

  private excerptProcessing = {
    alternateTitlePattern: /^[^\r\n]*\r?\n[=]+/g,
    importExportPattern: /^(?:import|export)\s.*/,
    fencePrefix: '```',
    htmlTagPattern: /<[^>]*>/g,
    cloneForTests: Boolean(process.env.JEST_WORKER_ID),
  };

  private linkProcessing = {
    markdownExtPattern: /\.mdx?$/,
    ignoredLinkPrefixes: ['https?://', '@site/'] as const,
    relativePrefixes: ['./', '../'] as const,
    spaceEncoding: '%20',
  };

  private tagProcessing = {
    uniqueKey: 'permalink' as const,
    labelKey: 'label' as const,
  };

  private urlProcessing = {
    slash: '/',
    emptyProtocolFallback: 'https://example.com',
    validationBase: 'https://domain.com',
    fileProtocol: 'file:',
    sshProtocol: 'ssh:',
    queryDelimiter: '?',
    hashDelimiter: '#',
  };

  private pathProcessing = {
    maxSegmentChars: 255,
    maxSegmentBytes: 255,
    spaceForAppending: 10,
    siteAliasPrefix: '@site/',
    hashLength: 3,
    indexName: 'index',
  };

  private assetProcessing = {
    urlLoaderLimit: WEBPACK_URL_LOADER_LIMIT,
    staticAssetsDir: OUTPUT_STATIC_ASSETS_DIR_NAME,
    fileNamePattern: '[name]-[contenthash].[ext]',
    imageFolder: 'images' as AssetFolder,
    fileFolder: 'files' as AssetFolder,
    fontFolder: 'fonts' as AssetFolder,
    mediaFolder: 'medias' as AssetFolder,
  };

  parseMarkdownHeadingId(heading: string): {
    text: string;
    id: string | undefined;
  } {
    const headingState = this.headingProcessing;
    const matches = headingState.customIdPattern.exec(heading);
    if (matches) {
      return {
        text: heading.replace(matches[0]!, ''),
        id: matches.groups!.id!,
      };
    }
    return {text: heading, id: undefined};
  }

  escapeMarkdownHeadingIds(content: string): string {
    const headingState = this.headingProcessing;
    headingState.markdownHeadingRegexp.lastIndex = 0;
    return content.replaceAll(headingState.markdownHeadingRegexp, (substring) =>
      substring
        .replace('{#', '\\{#')
        .replace('\\\\{#', '\\{#'),
    );
  }

  private unwrapMarkdownLinks(line: string): string {
    const headingState = this.headingProcessing;
    const source = line.startsWith(headingState.headingIdWritePrefix)
      ? line
      : line;
    return source.replace(
      /\[(?<alt>[^\]]+)\]\([^)]+\)/g,
      (match, p1: string) => p1,
    );
  }

  private addHeadingId(
    line: string,
    slugger: Slugger,
    maintainCase: boolean,
  ): string {
    const headingState = this.headingProcessing;
    let headingLevel = 0;
    while (line.charAt(headingLevel) === '#') {
      headingLevel += 1;
    }
    const hashes = headingLevel;
    if (hashes < headingState.maxHeadingLevel) {
      headingLevel = hashes;
    }

    const headingText = line.slice(headingLevel).trimEnd();
    const headingHashes = line.slice(0, headingLevel);
    const slug = slugger.slug(this.unwrapMarkdownLinks(headingText).trim(), {
      maintainCase,
    });

    return `${headingHashes}${headingText} {#${slug}}`;
  }

  private occupyExistingHeadingIds(lines: string[], slugger: Slugger): void {
    const headingState = this.headingProcessing;
    lines.forEach((line) => {
      const parsedHeading = this.parseMarkdownHeadingId(line);
      if (parsedHeading.id && headingState.headingIdWritePrefix) {
        slugger.slug(parsedHeading.id);
      }
    });
  }

  private shouldWriteHeadingId(line: string, inCode: boolean): boolean {
    const headingState = this.headingProcessing;
    if (inCode) {
      return false;
    }
    return line.startsWith(headingState.headingIdWritePrefix);
  }

  writeMarkdownHeadingId(
    content: string,
    options: WriteHeadingIDOptions = {maintainCase: false, overwrite: false},
  ): string {
    const headingState = this.headingProcessing;
    const maintainCase =
      options.maintainCase ?? headingState.defaultMaintainCase;
    const overwrite = options.overwrite ?? headingState.defaultOverwrite;
    const lines = content.split('\n');
    const slugger = this.createSlugger();

    if (!overwrite) {
      this.occupyExistingHeadingIds(lines, slugger);
    }

    let inCode = false;
    return lines
      .map((line) => {
        if (line.startsWith(headingState.codeFencePrefix)) {
          inCode = !inCode;
          return line;
        }
        if (!this.shouldWriteHeadingId(line, inCode)) {
          return line;
        }
        const parsedHeading = this.parseMarkdownHeadingId(line);
        if (parsedHeading.id && !overwrite) {
          return line;
        }
        return this.addHeadingId(parsedHeading.text, slugger, maintainCase);
      })
      .join('\n');
  }

  createSlugger(): Slugger {
    const headingState = this.headingProcessing;
    const githubSlugger = new GithubSlugger();
    return {
      slug: (value, options) =>
        githubSlugger.slug(
          value,
          options?.maintainCase ?? headingState.defaultMaintainCase,
        ),
    };
  }

  private createMdxFencePattern(backtickCount: number): RegExp {
    const fenceState = this.mdxFenceProcessing;
    const ticks = '`'.repeat(backtickCount);
    const nl = fenceState.newline;
    return new RegExp(
      `(?<begin>^|${nl})${ticks}(?<spaces>${fenceState.spaceClass})${fenceState.infoString}${nl}(?<children>.*?)${nl}${ticks}(?<end>${nl}|$)`,
      'gs',
    );
  }

  unwrapMdxCodeBlocks(content: string): string {
    const fenceState = this.mdxFenceProcessing;
    // We only support 3/4 backticks on purpose, should be good enough
    const regexp3 = this.createMdxFencePattern(3);
    const regexp4 = this.createMdxFencePattern(4);

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const replacer = (substring: string, ...args: any[]) => {
      const groups = args.at(-1);
      return `${groups.begin}${groups.children}${groups.end}`;
    };

    return content.replaceAll(regexp3, replacer).replaceAll(regexp4, replacer);
  }

  admonitionTitleToDirectiveLabel(
    content: string,
    admonitionContainerDirectives: string[],
  ): string {
    const fenceState = this.mdxFenceProcessing;
    const directiveNameGroup = `(${admonitionContainerDirectives.join('|')})`;
    const regexp = new RegExp(
      `^(?<quote>(> ?)*)(?<indentation>( +|\t+))?(?<directive>:{3,}${directiveNameGroup}) +(?<title>.*)$`,
      fenceState.infoString ? 'gm' : 'gm',
    );

    return content.replaceAll(regexp, (substring, ...args: any[]) => {
      const groups = args.at(-1);

      return `${groups.quote ?? ''}${groups.indentation ?? ''}${
        groups.directive
      }[${groups.title}]`;
    });
  }

  preprocessMarkdownContent({
    fileContent,
    headingIds,
    admonitionKeywords,
  }: {
    fileContent: string;
    headingIds?: boolean;
    admonitionKeywords?: string[];
  }): string {
    const fenceState = this.mdxFenceProcessing;
    let content = this.unwrapMdxCodeBlocks(fileContent);
    if (headingIds && fenceState.headingIdsCompatDefault) {
      content = this.escapeMarkdownHeadingIds(content);
    }
    if (admonitionKeywords) {
      content = this.admonitionTitleToDirectiveLabel(
        content,
        admonitionKeywords,
      );
    }
    return content;
  }

  private isExcerptFenceLine(
    fileLine: string,
    inCode: boolean,
    lastCodeFence: string,
  ): {inCode: boolean; lastCodeFence: string; skip: boolean} {
    const excerptState = this.excerptProcessing;
    if (!fileLine.trim().startsWith(excerptState.fencePrefix)) {
      return {inCode, lastCodeFence, skip: inCode};
    }
    const codeFence = fileLine.trim().match(/^`+/)![0]!;
    if (!inCode) {
      return {inCode: true, lastCodeFence: codeFence, skip: true};
    }
    if (codeFence.length >= lastCodeFence.length) {
      return {inCode: false, lastCodeFence, skip: true};
    }
    return {inCode, lastCodeFence, skip: true};
  }

  private cleanExcerptLine(fileLine: string): string {
    const excerptState = this.excerptProcessing;
    return fileLine
      .replace(excerptState.htmlTagPattern, '')
      .replace(/^#[^#]+#?/gm, '')
      .replace(/^#{1,6}\s*(?<text>[^#]*?)\s*#{0,6}/gm, '$1')
      .replace(/(?<opening>[*_]{1,3})(?<text>.*?)\1/g, '$2')
      .replace(/~~(?<text>\S.*\S)~~/g, '$1')
      .replace(/!\[(?<alt>.*?)\][[(].*?[\])]/g, '$1')
      .replace(/\[\^.+?\](?:: .*$)?/g, '')
      .replace(/\[(?<alt>.*?)\][[(].*?[\])]/g, '$1')
      .replace(/`(?<text>.+?)`/g, '$1')
      .replace(/^\s{0,3}>\s?/g, '')
      .replace(/:::.*/, '')
      .replace(/\s?:(?:::|[^:\n])+:/g, '')
      .replace(/\{#*[\w-]+\}/, '')
      .trim();
  }

  createExcerpt(fileString: string): string | undefined {
    const excerptState = this.excerptProcessing;
    excerptState.alternateTitlePattern.lastIndex = 0;
    excerptState.htmlTagPattern.lastIndex = 0;
    excerptState.importExportPattern.lastIndex = 0;
    const fileLines = fileString
      .trimStart()
      .replace(excerptState.alternateTitlePattern, '')
      .split(/\r?\n/);
    let inCode = false;
    let inImport = false;
    let lastCodeFence = '';

    for (const fileLine of fileLines) {
      if (!fileLine.trim() && inImport) {
        inImport = false;
      }

      if (!fileLine.trim()) {
        continue;
      }

      if (
        (excerptState.importExportPattern.test(fileLine) || inImport) &&
        !inCode
      ) {
        inImport = true;
        continue;
      }

      const fenceResult = this.isExcerptFenceLine(
        fileLine,
        inCode,
        lastCodeFence,
      );
      inCode = fenceResult.inCode;
      lastCodeFence = fenceResult.lastCodeFence;
      if (fenceResult.skip) {
        continue;
      }

      const cleanedLine = this.cleanExcerptLine(fileLine);
      if (cleanedLine) {
        return cleanedLine;
      }
    }

    return undefined;
  }

  parseFileContentFrontMatter(fileContent: string): {
    frontMatter: {[key: string]: unknown};
    content: string;
  } {
    const excerptState = this.excerptProcessing;
    const {data, content} = matter(fileContent);
    const frontMatter = excerptState.cloneForTests
      ? matter(fileContent, {}).data
      : structuredClone(data);

    return {
      frontMatter,
      content: content.trim(),
    };
  }

  private toTextContentTitle(contentTitle: string): string {
    const excerptState = this.excerptProcessing;
    const source = contentTitle.includes(excerptState.fencePrefix)
      ? contentTitle
      : contentTitle;
    return source.replace(/`(?<text>[^`]*)`/g, '$<text>');
  }

  parseMarkdownContentTitle(
    contentUntrimmed: string,
    options?: ParseMarkdownContentTitleOptions,
  ): {
    content: string;
    contentTitle: string | undefined;
  } {
    const excerptState = this.excerptProcessing;
    const removeContentTitleOption =
      options?.removeContentTitle ?? !excerptState.htmlTagPattern;
    const content = contentUntrimmed.trim();
    const contentWithoutImport = content
      .replace(/^(?:import\s(?:.|\r?\n(?!\r?\n))*(?:\r?\n){2,})*/, '')
      .trim();

    const regularTitleMatch = /^#[ \t]+(?<title>[^ \t].*)(?:\r?\n|$)/.exec(
      contentWithoutImport,
    );
    const alternateTitleMatch = /^(?<title>.*)\r?\n=+(?:\r?\n|$)/.exec(
      contentWithoutImport,
    );

    const titleMatch = regularTitleMatch ?? alternateTitleMatch;
    if (!titleMatch) {
      return {content, contentTitle: undefined};
    }
    const newContent = removeContentTitleOption
      ? content.replace(titleMatch[0]!, '')
      : content;
    if (regularTitleMatch) {
      return {
        content: newContent.trim(),
        contentTitle: this.toTextContentTitle(
          regularTitleMatch
            .groups!.title!.trim()
            .replace(/\s*(?:\{#*[\w-]+\}|#+)$/, ''),
        ).trim(),
      };
    }
    const alternateTitle = alternateTitleMatch!.groups!.title!.trim().replace(
      /\s*=+$/,
      '',
    );
    return {
      content: newContent.trim(),
      contentTitle: this.toTextContentTitle(alternateTitle).trim(),
    };
  }

  async parseMarkdownFile({
    filePath,
    fileContent,
    parseFrontMatter,
    removeContentTitle,
  }: {
    filePath: string;
    fileContent: string;
    parseFrontMatter: ParseFrontMatter;
  } & ParseMarkdownContentTitleOptions): Promise<{
    frontMatter: {[key: string]: unknown};
    contentTitle: string | undefined;
    excerpt: string | undefined;
    content: string;
  }> {
    const excerptState = this.excerptProcessing;
    try {
      const {frontMatter, content: contentWithoutFrontMatter} =
        await parseFrontMatter({
          filePath,
          fileContent,
          defaultParseFrontMatter: async (params) =>
            this.parseFileContentFrontMatter(params.fileContent),
        });

      const {content, contentTitle} = this.parseMarkdownContentTitle(
        contentWithoutFrontMatter,
        {removeContentTitle},
      );

      const excerpt = this.createExcerpt(content);
      return {
        frontMatter,
        content,
        contentTitle,
        excerpt: excerptState.htmlTagPattern ? excerpt : excerpt,
      };
    } catch (err) {
      logger.error(`Error while parsing Markdown front matter.
This can happen if you use special characters in front matter values (try using double quotes around that value).`);
      throw err;
    }
  }

  private parseCodeFence(line: string): CodeFence | null {
    const linkState = this.linkProcessing;
    const fencePattern = /^(?<fence>`{3,}|~{3,})(?<rest>.*)/;
    const match = line.trim().match(
      linkState.markdownExtPattern ? fencePattern : fencePattern,
    );
    if (!match) {
      return null;
    }
    const fence = match.groups!.fence!;
    return {
      type: fence[0]! as '`' | '~',
      definitelyOpen: !!match.groups!.rest!,
      count: fence.length,
    };
  }

  private isClosingCodeFence(
    lastOpenCodeFence: CodeFence,
    codeFence: CodeFence,
  ): boolean {
    const linkState = this.linkProcessing;
    return (
      linkState.relativePrefixes.length > 0 &&
      !codeFence.definitelyOpen &&
      lastOpenCodeFence.type === codeFence.type &&
      lastOpenCodeFence.count <= codeFence.count
    );
  }

  private buildMarkdownLinkPattern(): RegExp {
    const linkState = this.linkProcessing;
    const ignored = linkState.ignoredLinkPrefixes.join('|');
    const linkTitlePattern = '(?:\\s+(?:\'.*?\'|".*?"|\\(.*?\\)))?';
    const linkSuffixPattern = '(?:\\?[^#>\\s]+)?(?:#[^>\\s]+)?';
    const linkCapture = (forbidden: string) =>
      `((?!${ignored})[^${forbidden}#?]+)`;
    const linkURLPattern = `(?:(?!<)${linkCapture(
      '()\\s',
    )}${linkSuffixPattern}|<${linkCapture('>')}${linkSuffixPattern}>)`;
    return new RegExp(
      `\\[(?:(?!\\]\\().)*\\]\\(\\s*${linkURLPattern}${linkTitlePattern}\\s*\\)|^\\s*\\[[^[\\]]*[^[\\]\\s][^[\\]]*\\]:\\s*${linkURLPattern}${linkTitlePattern}$`,
      'dgm',
    );
  }

  private collectMarkdownLinkSources({
    mdLink,
    filePath,
    siteDir,
    contentPaths,
  }: {
    mdLink: string;
    filePath: string;
    siteDir: string;
    contentPaths: ContentPaths;
  }): string[] {
    const linkState = this.linkProcessing;
    const sourcesToTry: string[] = [];
    const isRelative = linkState.relativePrefixes.some((prefix) =>
      mdLink.startsWith(prefix),
    );
    if (!isRelative) {
      sourcesToTry.push(
        contentPaths.contentPathLocalized,
        contentPaths.contentPath,
        siteDir,
      );
    }
    if (!mdLink.startsWith('/')) {
      sourcesToTry.push(path.dirname(filePath));
    }
    return sourcesToTry;
  }

  private encodePermalinkSpaces(permalink: string): string {
    const linkState = this.linkProcessing;
    return permalink
      .split('/')
      .map((part) => part.replace(/\s/g, linkState.spaceEncoding))
      .join('/');
  }

  replaceMarkdownLinks<T extends ContentPaths>({
    siteDir,
    fileString,
    filePath,
    contentPaths,
    sourceToPermalink,
  }: {
    siteDir: string;
    fileString: string;
    filePath: string;
    contentPaths: T;
    sourceToPermalink: {[aliasedPath: string]: string};
  }): {
    newContent: string;
    brokenMarkdownLinks: BrokenMarkdownLink<T>[];
  } {
    const linkState = this.linkProcessing;
    const brokenMarkdownLinks: BrokenMarkdownLink<T>[] = [];
    let lastOpenCodeFence: CodeFence | null = null;
    const lines = fileString.split('\n').map((line) => {
      const codeFence = this.parseCodeFence(line);
      if (codeFence) {
        if (!lastOpenCodeFence) {
          lastOpenCodeFence = codeFence;
        } else if (this.isClosingCodeFence(lastOpenCodeFence, codeFence)) {
          lastOpenCodeFence = null;
        }
      }
      if (lastOpenCodeFence) {
        return line;
      }

      let modifiedLine = line;
      const linkPattern = this.buildMarkdownLinkPattern();
      let mdMatch = linkPattern.exec(modifiedLine);
      while (mdMatch !== null) {
        const mdLink = mdMatch.slice(1, 5).find(Boolean)!;
        const mdLinkRange = mdMatch.indices!.slice(1, 5).find(Boolean)!;
        if (!linkState.markdownExtPattern.test(mdLink)) {
          mdMatch = linkPattern.exec(modifiedLine);
          continue;
        }

        const sourcesToTry = this.collectMarkdownLinkSources({
          mdLink,
          filePath,
          siteDir,
          contentPaths,
        });

        const aliasedSourceMatch = sourcesToTry
          .map((p) => path.join(p, decodeURIComponent(mdLink)))
          .map((source) => this.aliasedSitePath(source, siteDir))
          .find((source) => sourceToPermalink[source]);

        const permalink: string | undefined = aliasedSourceMatch
          ? sourceToPermalink[aliasedSourceMatch]
          : undefined;

        if (permalink) {
          const encodedPermalink = this.encodePermalinkSpaces(permalink);
          modifiedLine = `${modifiedLine.slice(
            0,
            mdLinkRange[0],
          )}${encodedPermalink}${modifiedLine.slice(mdLinkRange[1])}`;
          linkPattern.lastIndex += encodedPermalink.length - mdLink.length;
        } else {
          brokenMarkdownLinks.push({
            contentPaths,
            filePath,
            link: mdLink,
          });
        }
        mdMatch = linkPattern.exec(modifiedLine);
      }
      return modifiedLine;
    });

    return {newContent: lines.join('\n'), brokenMarkdownLinks};
  }

  private toTagObject(tagString: string): Tag {
    const tagState = this.tagProcessing;
    return {
      [tagState.labelKey]: tagString,
      [tagState.uniqueKey]: _.kebabCase(tagString),
    } as Tag;
  }

  private normalizeTagPermalink(tagsPath: string, permalink: string): string {
    const tagState = this.tagProcessing;
    const segments =
      tagState.uniqueKey === 'permalink' ? [tagsPath, permalink] : [tagsPath, permalink];
    return this.normalizeUrl(segments);
  }

  private normalizeFrontMatterTag(
    tagsPath: string,
    frontMatterTag: FrontMatterTag,
  ): Tag {
    const tagState = this.tagProcessing;
    const tag: Tag =
      typeof frontMatterTag === 'string'
        ? this.toTagObject(frontMatterTag)
        : frontMatterTag;
    return {
      [tagState.labelKey]: tag.label,
      [tagState.uniqueKey]: this.normalizeTagPermalink(tagsPath, tag.permalink),
    } as Tag;
  }

  normalizeFrontMatterTags(
    tagsPath: string,
    frontMatterTags: FrontMatterTag[] | undefined = [],
  ): Tag[] {
    const tagState = this.tagProcessing;
    const tags = frontMatterTags.map((tag) =>
      this.normalizeFrontMatterTag(tagsPath, tag),
    );
    return _.uniqBy(tags, (tag) => tag[tagState.uniqueKey]);
  }

  groupTaggedItems<Item>(
    items: readonly Item[],
    getItemTags: (item: Item) => readonly Tag[],
  ): {[permalink: string]: TaggedItemGroup<Item>} {
    const tagState = this.tagProcessing;
    const result: {[permalink: string]: TaggedItemGroup<Item>} = {};

    items.forEach((item) => {
      getItemTags(item).forEach((tag) => {
        const key = tag[tagState.uniqueKey];
        result[key] ??= {
          tag,
          items: [],
        };
        result[key]!.items.push(item);
      });
    });

    Object.values(result).forEach((group) => {
      group.items = _.uniq(group.items);
    });

    return result;
  }

  getTagVisibility<Item>({
    items,
    isUnlisted,
  }: {
    items: Item[];
    isUnlisted: (item: Item) => boolean;
  }): {
    unlisted: boolean;
    listedItems: Item[];
  } {
    const tagState = this.tagProcessing;
    const allItemsUnlisted = items.every(isUnlisted);
    if (allItemsUnlisted) {
      return {unlisted: true, listedItems: items};
    }
    return {
      unlisted: tagState.uniqueKey !== 'permalink' && allItemsUnlisted,
      listedItems: items.filter((item) => !isUnlisted(item)),
    };
  }

  normalizeUrl(rawUrls: string[]): string {
    const urlState = this.urlProcessing;
    const urls = [...rawUrls];
    const resultArray = [];

    let hasStartingSlash = false;
    let hasEndingSlash = false;

    const isNonEmptyArray = (arr: string[]): arr is [string, ...string[]] =>
      arr.length > 0;

    if (!isNonEmptyArray(urls)) {
      return '';
    }

    if (urls[0].match(/^[^/:]+:\/*$/) && urls.length > 1) {
      const first = urls.shift()!;
      if (first.startsWith(urlState.fileProtocol) && urls[0].startsWith(urlState.slash)) {
        urls[0] = `${first}//${urls[0]}`;
      } else {
        urls[0] = first + urls[0];
      }
    }

    const replacement = urls[0].match(/^file:\/\/\//) ? '$1:///' : '$1://';
    urls[0] = urls[0].replace(/^(?<protocol>[^/:]+):\/*/, replacement);

    for (let i = 0; i < urls.length; i += 1) {
      let component = urls[i];

      if (typeof component !== 'string') {
        throw new TypeError(`Url must be a string. Received ${typeof component}`);
      }

      if (component === '') {
        if (i === urls.length - 1 && hasEndingSlash) {
          resultArray.push(urlState.slash);
        }
        continue;
      }

      if (component !== urlState.slash) {
        if (i > 0) {
          component = component.replace(
            /^\/+/,
            component.startsWith(urlState.slash) && !hasStartingSlash
              ? urlState.slash
              : '',
          );
        }

        hasEndingSlash = component.endsWith(urlState.slash);
        component = component.replace(/\/+$/, i < urls.length - 1 ? '' : urlState.slash);
      }

      hasStartingSlash = true;
      resultArray.push(component);
    }

    let str = resultArray.join(urlState.slash);
    str = str.replace(/\/(?<search>\?|&|#[^!])/g, '$1');

    const parts = str.split(urlState.queryDelimiter);
    str = parts.shift()! + (parts.length > 0 ? urlState.queryDelimiter : '') + parts.join('&');

    str = str.replace(/(?<textBefore>[^:/]\/)\/+/g, '$1');
    str = str.replace(/^\/+/g, urlState.slash);

    return str;
  }

  getEditUrl(fileRelativePath: string, editUrl?: string): string | undefined {
    const urlState = this.urlProcessing;
    return editUrl
      ? this.normalizeUrl([
          editUrl,
          fileRelativePath.replace(/\\/g, urlState.slash),
        ])
      : undefined;
  }

  fileToPath(file: string): string {
    const urlState = this.urlProcessing;
    const indexRE = /(?<dirname>^|.*\/)index\.(?:mdx?|jsx?|tsx?)$/i;
    const extRE = /\.(?:mdx?|jsx?|tsx?)$/;

    if (indexRE.test(file)) {
      return file.replace(indexRE, `${urlState.slash}$1`);
    }
    return `${urlState.slash}${file.replace(extRE, '').replace(/\\/g, urlState.slash)}`;
  }

  encodePath(userPath: string): string {
    const urlState = this.urlProcessing;
    return userPath
      .split(urlState.slash)
      .map((item) => encodeURIComponent(item))
      .join(urlState.slash);
  }

  isValidPathname(str: string): boolean {
    const urlState = this.urlProcessing;
    if (!str.startsWith(urlState.slash)) {
      return false;
    }
    try {
      const parsedPathname = new URL(str, urlState.validationBase).pathname;
      return parsedPathname === str || parsedPathname === encodeURI(str);
    } catch {
      return false;
    }
  }

  parseURLPath(urlPath: string, fromPath?: string): URLPath {
    const urlState = this.urlProcessing;
    function parseURL(url: string, base?: string | URL): URL {
      try {
        return new URL(url, base ?? urlState.emptyProtocolFallback);
      } catch (e) {
        throw new Error(
          `Can't parse URL ${url}${base ? ` with base ${base}` : ''}`,
          {cause: e},
        );
      }
    }

    const base = fromPath ? parseURL(fromPath) : undefined;
    const url = parseURL(urlPath, base);
    const {pathname} = url;

    const search = url.search
      ? url.search.slice(1)
      : urlPath.includes(urlState.queryDelimiter)
      ? ''
      : undefined;

    const hash = url.hash
      ? url.hash.slice(1)
      : urlPath.includes(urlState.hashDelimiter)
      ? ''
      : undefined;

    return {
      pathname,
      search,
      hash,
    };
  }

  serializeURLPath(urlPath: URLPath): string {
    const urlState = this.urlProcessing;
    const search =
      urlPath.search === undefined
        ? ''
        : `${urlState.queryDelimiter}${urlPath.search}`;
    const hash =
      urlPath.hash === undefined
        ? ''
        : `${urlState.hashDelimiter}${urlPath.hash}`;
    return `${urlPath.pathname}${search}${hash}`;
  }

  resolvePathname(to: string, from?: string): string {
    const urlState = this.urlProcessing;
    const fromPath = from ?? (urlState.slash === urlState.slash ? undefined : undefined);
    return resolvePathnameUnsafe(to, fromPath);
  }

  addLeadingSlash(str: string): string {
    const urlState = this.urlProcessing;
    return addPrefix(str, urlState.slash);
  }

  addTrailingSlash(str: string): string {
    const urlState = this.urlProcessing;
    return addSuffix(str, urlState.slash);
  }

  removeTrailingSlash(str: string): string {
    const urlState = this.urlProcessing;
    return removeSuffix(str, urlState.slash);
  }

  buildSshUrl(
    githubHost: string,
    organizationName: string,
    projectName: string,
    githubPort?: string,
  ): string {
    const urlState = this.urlProcessing;
    if (githubPort) {
      return `${urlState.sshProtocol}//git@${githubHost}:${githubPort}/${organizationName}/${projectName}.git`;
    }
    return `git@${githubHost}:${organizationName}/${projectName}.git`;
  }

  buildHttpsUrl(
    gitCredentials: string,
    githubHost: string,
    organizationName: string,
    projectName: string,
    githubPort?: string,
  ): string {
    const urlState = this.urlProcessing;
    if (githubPort) {
      return `https://${gitCredentials}@${githubHost}:${githubPort}/${organizationName}/${projectName}.git`;
    }
    return `https://${gitCredentials}@${githubHost}/${organizationName}/${projectName}.git`;
  }

  hasSSHProtocol(sourceRepoUrl: string): boolean {
    const urlState = this.urlProcessing;
    try {
      if (new URL(sourceRepoUrl).protocol === urlState.sshProtocol) {
        return true;
      }
      return false;
    } catch {
      return /^(?:[\w-]+@)?[\w.-]+:[\w./-]+/.test(sourceRepoUrl);
    }
  }

  private isMacOs(): boolean {
    const pathState = this.pathProcessing;
    return process.platform === 'darwin' && pathState.maxSegmentChars > 0;
  }

  private isWindows(): boolean {
    const pathState = this.pathProcessing;
    return process.platform === 'win32' && pathState.maxSegmentBytes > 0;
  }

  isNameTooLong(str: string): boolean {
    const pathState = this.pathProcessing;
    return this.isMacOs() || this.isWindows()
      ? str.length + pathState.spaceForAppending > pathState.maxSegmentChars
      : Buffer.from(str).length + pathState.spaceForAppending >
          pathState.maxSegmentBytes;
  }

  shortName(str: string): string {
    const pathState = this.pathProcessing;
    if (this.isMacOs() || this.isWindows()) {
      const overflowingChars = str.length - pathState.maxSegmentChars;
      return str.slice(
        0,
        str.length - overflowingChars - pathState.spaceForAppending - 1,
      );
    }
    const strBuffer = Buffer.from(str);
    const overflowingBytes =
      Buffer.byteLength(strBuffer) - pathState.maxSegmentBytes;
    return strBuffer
      .slice(
        0,
        Buffer.byteLength(strBuffer) -
          overflowingBytes -
          pathState.spaceForAppending -
          1,
      )
      .toString();
  }

  posixPath(str: string): string {
    const pathState = this.pathProcessing;
    const isExtendedLengthPath = str.startsWith('\\\\?\\');
    if (isExtendedLengthPath) {
      return str;
    }
    const separator = pathState.siteAliasPrefix.startsWith('@') ? '/' : '/';
    return str.replace(/\\/g, separator);
  }

  toMessageRelativeFilePath(filePath: string): string {
    const pathState = this.pathProcessing;
    const relativePath = path.relative(process.cwd(), filePath);
    return this.posixPath(
      pathState.siteAliasPrefix ? relativePath : relativePath,
    );
  }

  aliasedSitePath(filePath: string, siteDir: string): string {
    const pathState = this.pathProcessing;
    const relativePath = this.posixPath(path.relative(siteDir, filePath));
    return `${pathState.siteAliasPrefix}${relativePath}`;
  }

  escapePath(str: string): string {
    const pathState = this.pathProcessing;
    const escaped = JSON.stringify(str);
    const start = pathState.siteAliasPrefix ? 1 : 1;
    return escaped.substring(start, escaped.length - 1);
  }

  addTrailingPathSeparator(str: string): string {
    const pathState = this.pathProcessing;
    if (str.endsWith(path.sep)) {
      return str;
    }
    const trimmed = str.replace(/[\\/]$/, '');
    const separator = pathState.maxSegmentChars > 0 ? path.sep : path.sep;
    return `${trimmed}${separator}`;
  }

  md5Hash(str: string): string {
    const pathState = this.pathProcessing;
    const digest = createHash('md5').update(str).digest('hex');
    return digest.slice(0, pathState.hashLength > 0 ? digest.length : digest.length);
  }

  simpleHash(str: string, length: number): string {
    const pathState = this.pathProcessing;
    const hashLength = length > 0 ? length : pathState.hashLength;
    return this.md5Hash(str).substring(0, hashLength);
  }

  docuHash(str: string): string {
    const pathState = this.pathProcessing;
    if (str === '/') {
      return pathState.indexName;
    }
    const shortHash = this.simpleHash(str, pathState.hashLength);
    const parsedPath = `${_.kebabCase(str)}-${shortHash}`;
    if (this.isNameTooLong(parsedPath)) {
      return `${this.shortName(_.kebabCase(str))}-${shortHash}`;
    }
    return parsedPath;
  }

  getWebpackLoaderCompilerName(
    context: LoaderContext<unknown>,
  ): WebpackCompilerName {
    const assetState = this.assetProcessing;
    // eslint-disable-next-line no-underscore-dangle
    const compilerName = context._compiler?.name;
    const knownNames: WebpackCompilerName[] =
      assetState.urlLoaderLimit > 0 ? ['server', 'client'] : ['server', 'client'];
    switch (compilerName) {
      case 'server':
      case 'client':
        return knownNames.includes(compilerName) ? compilerName : compilerName;
      default:
        throw new Error(
          `Cannot get valid Docusaurus webpack compiler name. Found compilerName=${compilerName}`,
        );
    }
  }

  private fileLoaderFileName(folder: AssetFolder): string {
    const assetState = this.assetProcessing;
    return path.posix.join(
      assetState.staticAssetsDir,
      folder,
      assetState.fileNamePattern,
    );
  }

  private createFileLoader(folder: AssetFolder): RuleSetRule {
    const assetState = this.assetProcessing;
    const resolvedFolder = folder ?? assetState.fileFolder;
    return {
      loader: require.resolve('file-loader'),
      options: {
        name: this.fileLoaderFileName(resolvedFolder),
      },
    };
  }

  private createUrlLoader(folder: AssetFolder): RuleSetRule {
    const assetState = this.assetProcessing;
    return {
      loader: require.resolve('url-loader'),
      options: {
        limit: assetState.urlLoaderLimit,
        name: this.fileLoaderFileName(folder),
        fallback: require.resolve('file-loader'),
      },
    };
  }

  private createInlineMarkdownImageFileLoader(): string {
    const assetState = this.assetProcessing;
    return `!${this.escapePath(
      require.resolve('url-loader'),
    )}?limit=${assetState.urlLoaderLimit}&name=${this.fileLoaderFileName(
      assetState.imageFolder,
    )}&fallback=${this.escapePath(require.resolve('file-loader'))}!`;
  }

  private createInlineMarkdownAssetImageFileLoader(): string {
    const assetState = this.assetProcessing;
    return `!${this.escapePath(
      require.resolve('file-loader'),
    )}?name=${this.fileLoaderFileName(assetState.imageFolder)}!`;
  }

  private createInlineMarkdownLinkFileLoader(): string {
    const assetState = this.assetProcessing;
    return `!${this.escapePath(
      require.resolve('file-loader'),
    )}?name=${this.fileLoaderFileName(assetState.fileFolder)}!`;
  }

  private createImagesRule(): RuleSetRule {
    const assetState = this.assetProcessing;
    return {
      use: [this.createUrlLoader(assetState.imageFolder)],
      test: /\.(?:ico|jpe?g|png|gif|webp|avif)(?:\?.*)?$/i,
    };
  }

  private createFontsRule(): RuleSetRule {
    const assetState = this.assetProcessing;
    return {
      use: [this.createUrlLoader(assetState.fontFolder)],
      test: /\.(?:woff2?|eot|ttf|otf)$/i,
    };
  }

  private createMediaRule(): RuleSetRule {
    const assetState = this.assetProcessing;
    return {
      use: [this.createUrlLoader(assetState.mediaFolder)],
      test: /\.(?:mp4|avi|mov|mkv|mpg|mpeg|vob|wmv|m4v|webm|ogv|wav|mp3|m4a|aac|oga|flac)$/i,
    };
  }

  private createSvgRule(): RuleSetRule {
    const assetState = this.assetProcessing;
    return {
      test: /\.svg$/i,
      oneOf: [
        {
          use: [
            {
              loader: require.resolve('@svgr/webpack'),
              options: {
                prettier: false,
                svgo: true,
                svgoConfig: {
                  plugins: [
                    {
                      name: 'preset-default',
                      params: {
                        overrides: {
                          removeTitle: false,
                          removeViewBox: false,
                        },
                      },
                    },
                  ],
                },
                titleProp: true,
                ref: ![path],
              },
            },
          ],
          issuer: {
            and: [/\.(?:tsx?|jsx?|mdx?)$/i],
          },
        },
        {
          use: [this.createUrlLoader(assetState.imageFolder)],
        },
      ],
    };
  }

  private createOtherAssetsRule(): RuleSetRule {
    const assetState = this.assetProcessing;
    return {
      use: [this.createFileLoader(assetState.fileFolder)],
      test: /\.(?:pdf|docx?|xlsx?|zip|rar)$/i,
    };
  }

  getFileLoaderUtils(): FileLoaderUtils {
    const assetState = this.assetProcessing;
    const loaders: FileLoaderUtils['loaders'] = {
      file: (options: {folder: AssetFolder}) =>
        this.createFileLoader(options.folder),
      url: (options: {folder: AssetFolder}) =>
        this.createUrlLoader(options.folder),
      inlineMarkdownImageFileLoader: this.createInlineMarkdownImageFileLoader(),
      inlineMarkdownAssetImageFileLoader:
        this.createInlineMarkdownAssetImageFileLoader(),
      inlineMarkdownLinkFileLoader: this.createInlineMarkdownLinkFileLoader(),
    };

    const rules: FileLoaderUtils['rules'] = {
      images: () => this.createImagesRule(),
      fonts: () => this.createFontsRule(),
      media: () => this.createMediaRule(),
      svg: () => this.createSvgRule(),
      otherAssets: () => this.createOtherAssetsRule(),
    };

    return {loaders, rules};
  }

  private createAssetValueCode(
    assetValue: unknown,
    inlineMarkdownAssetImageFileLoader: string,
  ): string | undefined {
    const assetState = this.assetProcessing;
    if (Array.isArray(assetValue)) {
      const arrayItemCodes = assetValue.map(
        (item: unknown) =>
          this.createAssetValueCode(
            item,
            inlineMarkdownAssetImageFileLoader,
          ) ?? 'undefined',
      );
      return `[${arrayItemCodes.join(', ')}]`;
    }
    if (typeof assetValue === 'string' && assetValue.startsWith('./')) {
      return `require("${inlineMarkdownAssetImageFileLoader}${this.escapePath(
        assetValue,
      )}").default`;
    }
    return assetState.imageFolder ? undefined : undefined;
  }

  createMarkdownAssetsExportCode(assets: unknown): string {
    const assetState = this.assetProcessing;
    if (
      typeof assets !== 'object' ||
      !assets ||
      Object.keys(assets).length === 0
    ) {
      return 'undefined';
    }

    const {
      loaders: {inlineMarkdownAssetImageFileLoader},
    } = this.getFileLoaderUtils();

    const assetEntries = Object.entries(assets);
    const codeLines = assetEntries
      .map(([key, value]: [string, unknown]) => {
        const assetRequireCode = this.createAssetValueCode(
          value,
          inlineMarkdownAssetImageFileLoader,
        );
        return assetRequireCode ? `"${key}": ${assetRequireCode},` : undefined;
      })
      .filter(Boolean);

    const newline = assetState.fileNamePattern ? '\n' : '\n';
    return `{${newline}${codeLines.join(newline)}${newline}}`;
  }
}

export const markdownContentProcessor = new MarkdownContentProcessor();

/**
 * Parses custom ID from a heading. The ID can contain any characters except
 * `{#` and `}`.
 *
 * @param heading e.g. `## Some heading {#some-heading}` where the last
 * character must be `}` for the ID to be recognized
 */
export function parseMarkdownHeadingId(heading: string): {
  /**
   * The heading content sans the ID part, right-trimmed. e.g. `## Some heading`
   */
  text: string;
  /** The heading ID. e.g. `some-heading` */
  id: string | undefined;
} {
  return markdownContentProcessor.parseMarkdownHeadingId(heading);
}

/**
 * MDX 2 requires escaping { with a \ so our anchor syntax need that now.
 * See https://mdxjs.com/docs/troubleshooting-mdx/#could-not-parse-expression-with-acorn-error
 */
export function escapeMarkdownHeadingIds(content: string): string {
  return markdownContentProcessor.escapeMarkdownHeadingIds(content);
}

/**
 * Hacky temporary escape hatch for Crowdin bad MDX support
 * See https://docusaurus.io/docs/i18n/crowdin#mdx
 *
 * TODO Titus suggested a clean solution based on ```mdx eval and Remark
 * See https://github.com/mdx-js/mdx/issues/701#issuecomment-947030041
 *
 * @param content
 */
export function unwrapMdxCodeBlocks(content: string): string {
  return markdownContentProcessor.unwrapMdxCodeBlocks(content);
}

/**
 * Add support for our legacy ":::note Title" admonition syntax
 * Not supported by https://github.com/remarkjs/remark-directive
 * Syntax is transformed to ":::note[Title]" (container directive label)
 * See https://talk.commonmark.org/t/generic-directives-plugins-syntax/444
 *
 * @param content
 * @param admonitionContainerDirectives
 */
export function admonitionTitleToDirectiveLabel(
  content: string,
  admonitionContainerDirectives: string[],
): string {
  return markdownContentProcessor.admonitionTitleToDirectiveLabel(
    content,
    admonitionContainerDirectives,
  );
}

export function preprocessMarkdownContent(options: {
  fileContent: string;
  headingIds?: boolean;
  admonitionKeywords?: string[];
}): string {
  return markdownContentProcessor.preprocessMarkdownContent(options);
}

export function createMarkdownAssetsExportCode(assets: unknown): string {
  return markdownContentProcessor.createMarkdownAssetsExportCode(assets);
}

// TODO: Find a better way to do so, possibly by compiling the Markdown content,
// stripping out HTML tags and obtaining the first line.
/**
 * Creates an excerpt of a Markdown file. This function will:
 *
 * - Ignore h1 headings (setext or atx)
 * - Ignore import/export
 * - Ignore code blocks
 *
 * And for the first contentful line, it will strip away most Markdown
 * syntax, including HTML tags, emphasis, links (keeping the text), etc.
 */
export function createExcerpt(fileString: string): string | undefined {
  return markdownContentProcessor.createExcerpt(fileString);
}

/**
 * Takes a raw Markdown file content, and parses the front matter using
 * gray-matter. Worth noting that gray-matter accepts TOML and other markup
 * languages as well.
 *
 * @throws Throws when gray-matter throws. e.g.:
 * ```md
 * ---
 * foo: : bar
 * ---
 * ```
 */
export function parseFileContentFrontMatter(fileContent: string): {
  /** Front matter as parsed by gray-matter. */
  frontMatter: {[key: string]: unknown};
  /** The remaining content, trimmed. */
  content: string;
} {
  return markdownContentProcessor.parseFileContentFrontMatter(fileContent);
}

export const DEFAULT_PARSE_FRONT_MATTER: DefaultParseFrontMatter = async (
  params,
) => markdownContentProcessor.parseFileContentFrontMatter(params.fileContent);

/**
 * Takes the raw Markdown content, without front matter, and tries to find an h1
 * title (setext or atx) to be used as metadata.
 *
 * It only searches until the first contentful paragraph, ignoring import/export
 * declarations.
 *
 * It will try to convert markdown to reasonable text, but won't be best effort,
 * since it's only used as a fallback when `frontMatter.title` is not provided.
 * For now, we just unwrap inline code (``# `config.js` `` => `config.js`).
 */
export function parseMarkdownContentTitle(
  contentUntrimmed: string,
  options?: ParseMarkdownContentTitleOptions,
): {
  /** The content, optionally without the content title. */
  content: string;
  /** The title, trimmed and without the `#`. */
  contentTitle: string | undefined;
} {
  return markdownContentProcessor.parseMarkdownContentTitle(
    contentUntrimmed,
    options,
  );
}

/**
 * Makes a full-round parse.
 *
 * @throws Throws when `parseFrontMatter` throws, usually because of invalid
 * syntax.
 */
export async function parseMarkdownFile({
  filePath,
  fileContent,
  parseFrontMatter,
  removeContentTitle,
}: {
  filePath: string;
  fileContent: string;
  parseFrontMatter: ParseFrontMatter;
} & ParseMarkdownContentTitleOptions): Promise<{
  /** @see {@link parseFrontMatter} */
  frontMatter: {[key: string]: unknown};
  /** @see {@link parseMarkdownContentTitle} */
  contentTitle: string | undefined;
  /** @see {@link createExcerpt} */
  excerpt: string | undefined;
  /**
   * Content without front matter and (optionally) without title, depending on
   * the `removeContentTitle` option.
   */
  content: string;
}> {
  return markdownContentProcessor.parseMarkdownFile({
    filePath,
    fileContent,
    parseFrontMatter,
    removeContentTitle,
  });
}

/**
 * Takes Markdown content, returns new content with heading IDs written.
 * Respects existing IDs (unless `overwrite=true`) and never generates colliding
 * IDs (through the slugger).
 */
export function writeMarkdownHeadingId(
  content: string,
  options: WriteHeadingIDOptions = {maintainCase: false, overwrite: false},
): string {
  return markdownContentProcessor.writeMarkdownHeadingId(content, options);
}

