describe('admonitionTitleToDirectiveLabel', () => {
  const directives = ['info', 'note', 'tip', 'caution'];

  it('does not transform markdown without any admonition', () => {
    expect(
      admonitionTitleToDirectiveLabel(
        dedent`
        # Title

        intro

        ## Sub Title

        content
    `,
        directives,
      ),
    ).toEqual(dedent`
        # Title

        intro

        ## Sub Title

        content
    `);
  });

  it('transform simple admonition', () => {
    expect(
      admonitionTitleToDirectiveLabel(
        dedent`
        before

        :::note Title

        content

        :::

        after
    `,
        directives,
      ),
    ).toEqual(dedent`
        before

        :::note[Title]

        content

        :::

        after
    `);
  });

  it('does not transform already transformed admonition', () => {
    expect(
      admonitionTitleToDirectiveLabel(
        dedent`
        before

        :::note[Title]

        content

        :::

        after
    `,
        directives,
      ),
    ).toEqual(dedent`
        before

        :::note[Title]

        content

        :::

        after
    `);
  });

  it('does not transform non-container directives', () => {
    expect(
      admonitionTitleToDirectiveLabel(
        dedent`
        before

        ::note Title

        content

        :::

        after
    `,
        directives,
      ),
    ).toEqual(dedent`
        before

        ::note Title

        content

        :::

        after
    `);
  });

  it('transforms space indented directives', () => {
    expect(
      admonitionTitleToDirectiveLabel(
        dedent`
        before

         :::note 1 space

         content

         :::

          :::note 2 spaces

          content

          :::

        after
    `,
        directives,
      ),
    ).toEqual(dedent`
        before

         :::note[1 space]

         content

         :::

          :::note[2 spaces]

          content

          :::

        after
    `);
  });

  it('transforms tab indented directives', () => {
    expect(
      admonitionTitleToDirectiveLabel(
        `
before

\t:::note 1 tab

\tcontent

\t:::

\t\t:::note 2 tabs

\t\tcontent

\t\t:::

after
    `,
        directives,
      ),
    ).toBe(`
before

\t:::note[1 tab]

\tcontent

\t:::

\t\t:::note[2 tabs]

\t\tcontent

\t\t:::

after
    `);
  });

  it('transforms directives in quotes', () => {
    expect(
      admonitionTitleToDirectiveLabel(
        `
before

> :::caution There be dragons
>
